// Spanish AI — Livro online de espanhol (A1 → C2).
// Conteúdo estruturado em capítulos com teoria, exemplos, léxico,
// exercícios de fixação por tópico e prova final por nível.
//
// As explicações são apresentadas no idioma da interface (PT/EN).
// Os exemplos e palavras-alvo permanecem em ESPANHOL (conteúdo-alvo).

import type { LevelId } from "@/data/games";

export type ExerciseType = "multiple-choice" | "fill-blank" | "translate";

export interface Exercise {
  id: string;
  type: ExerciseType;
  question: string;
  questionEn?: string;
  options?: string[];
  optionsEn?: string[];
  answer: string;
  explanation?: string;
  explanationEn?: string;
}

export interface LexiconEntry {
  es: string;
  pt: string;
  en?: string;
  example?: string;
  tag?: "profesional" | "coloquial" | "formal" | "expresión";
}

export interface Topic {
  id: string;
  title: string;
  titleEn?: string;
  blocks: TopicBlock[];
  exercises: Exercise[];
}

export type TopicBlock =
  | { kind: "paragraph"; text: string; textEn?: string }
  | { kind: "heading"; text: string; textEn?: string }
  | { kind: "example"; es: string; pt: string; en?: string }
  | { kind: "list"; items: string[]; itemsEn?: string[] }
  | { kind: "table"; headers: string[]; headersEn?: string[]; rows: string[][]; rowsEn?: string[][] }
  | { kind: "tip"; text: string; textEn?: string };

export interface Chapter {
  id: string;
  number: number;
  title: string;
  titleEn?: string;
  summary: string;
  summaryEn?: string;
  topics: Topic[];
  lexicon: LexiconEntry[];
  /** Perguntas dedicadas do quiz (diferentes dos exercícios). */
  quiz?: Exercise[];
  /** Palavras de vocabulário extra para flashcards (diferentes do léxico). */
  flashcards?: LexiconEntry[];
  /** Resumo curto para a aba Revisão. */
  briefReview?: string;
  briefReviewEn?: string;
}

export interface CourseLevel {
  level: LevelId;
  title: string;
  description: string;
  chapters: Chapter[];
  exam: Exercise[];
  /** Banco rotativo da prova final — preenchido em runtime via exam-banks.ts. */
  examBank?: import("./exam-banks").ExamBank;
}

// Helper to pick localized text. Use in components: pickL(block.text, block.textEn, locale)
export const pickL = (pt: string, en: string | undefined, locale: "pt" | "en"): string =>
  locale === "en" && en ? en : pt;

export const pickLArr = (pt: string[], en: string[] | undefined, locale: "pt" | "en"): string[] =>
  locale === "en" && en ? en : pt;

