      quiz: [
        { id: "c1-10-q1", type: "multiple-choice", question: "Modelo de pronúncia do curso:", options: ["andaluz", "castelhano peninsular centro-norte", "rioplatense"], answer: "castelhano peninsular centro-norte", questionEn: "The course's pronunciation model:", optionsEn: ["Andalusian", "north-central peninsular Spanish", "Rioplatense"], explanation: "É o modelo de referência; o seseo e outras variantes são igualmente corretos.", explanationEn: "It's the reference model; seseo and other varieties are equally correct." },
        { id: "c1-10-q2", type: "multiple-choice", question: "'casa' e 'caza' soam diferentes:", options: ["na Espanha centro-norte", "em toda a América Latina", "em nenhum lugar"], answer: "na Espanha centro-norte", explanation: "Com seseo (América Latina, Canárias, parte da Andaluzia) soam iguais.", explanationEn: "With seseo (Latin America, Canaries, parts of Andalusia) they sound the same.", questionEn: "'casa' and 'caza' sound different:", optionsEn: ["in north-central Spain", "throughout Latin America", "nowhere"] },
        { id: "c1-10-q3", type: "multiple-choice", question: "Quantas vogais tem o espanhol?", options: ["5", "7", "12"], answer: "5", explanation: "A, E, I, O, U — sem vogais abertas/fechadas nem nasais.", explanationEn: "A, E, I, O, U — no open/closed or nasal vowels.", questionEn: "How many vowels does Spanish have?" },
        { id: "c1-10-q4", type: "multiple-choice", question: "'Música' leva tilde porque é:", options: ["esdrújula", "aguda terminada em vogal", "llana terminada em consoante"], answer: "esdrújula", explanation: "Todas as esdrújulas levam tilde.", explanationEn: "All esdrújulas take a tilde.", questionEn: "'Música' takes a tilde because it is:", optionsEn: ["esdrújula", "aguda ending in a vowel", "llana ending in a consonant"] },
        { id: "c1-10-q5", type: "multiple-choice", question: "'Canción' leva tilde porque é:", options: ["aguda terminada em N", "llana", "esdrújula"], answer: "aguda terminada em N", explanation: "Agudas terminadas em vogal, N ou S levam tilde.", explanationEn: "Agudas ending in a vowel, N or S take a tilde.", questionEn: "'Canción' takes a tilde because it is:", optionsEn: ["aguda ending in N", "llana", "esdrújula"] },
        { id: "c1-10-q6", type: "multiple-choice", question: "Complete: '___ quieres, te ayudo.'", options: ["Si", "Sí"], answer: "Si", explanation: "SI condicional sem tilde; SÍ (afirmação) com tilde.", explanationEn: "Conditional SI has no tilde; SÍ (yes) does.", questionEn: "Complete: '___ quieres, te ayudo.'" },
        { id: "c1-10-q7", type: "multiple-choice", question: "O H em espanhol:", options: ["é sempre mudo", "soa como /x/", "soa como /h/ inglês"], answer: "é sempre mudo", explanation: "hola, hacer, ahora: o H não se pronuncia.", explanationEn: "hola, hacer, ahora: H is silent.", questionEn: "In Spanish, the letter H:", optionsEn: ["is always silent", "sounds like /x/", "sounds like English /h/"] },
        { id: "c1-10-q8", type: "multiple-choice", question: "Rádios recomendados para shadowing peninsular:", options: ["Radio Nacional e Cadena SER", "só rádios brasileiras", "podcasts em inglês"], answer: "Radio Nacional e Cadena SER", explanation: "Fontes com castelhano peninsular padrão.", explanationEn: "Sources with standard peninsular Spanish.", questionEn: "Recommended radio stations for peninsular shadowing:", optionsEn: ["Radio Nacional and Cadena SER", "only Brazilian radio", "English podcasts"] },
        { id: "c1-10-q9", type: "multiple-choice", question: "Qual frase está correta?", options: ["¿Cómo te llamas?", "¿Como te llamas?", "¿Cómo té llamas?"], answer: "¿Cómo te llamas?", explanation: "CÓMO interrogativo leva tilde; TE pronome não.", explanationEn: "Interrogative CÓMO takes a tilde; the pronoun TE doesn't.", questionEn: "Which sentence is correct?" },
        { id: "c1-10-q10", type: "multiple-choice", question: "Erro comum de lusófonos com 'tomate':", options: ["pronunciar o E final como /i/ ('tomati')", "pronunciar o T", "acentuar o O"], answer: "pronunciar o E final como /i/ ('tomati')", explanation: "As vogais finais não se reduzem nem viram /i/.", explanationEn: "Final vowels don't reduce or turn into /i/.", questionEn: "Common Portuguese-speaker error with 'tomate':", optionsEn: ["pronouncing the final E as /i/ ('tomati')", "pronouncing the T", "stressing the O"] },
      ],
